CATALOGS = {"en": {}}
for _index, _code in enumerate(tuple(LANGUAGES)[1:]):
    CATALOGS[_code] = {source: translations[_index] for source, translations in TRANSLATIONS.items()}


def translate(text: str, language: str) -> str:
    catalogue = CATALOGS[language]
    if text in catalogue:
        return catalogue[text]
    numbered = re.fullmatch(r"(\d+\.\s+)(.+)", text)
    if numbered and numbered[2] in catalogue:
        return numbered[1] + catalogue[numbered[2]]
    return text


def instructions(language: str) -> str:
    first, second = EXAMPLES[language]
    steps = [
        "Source SRT (to synchronize)", "Processing device", "Hearing-impaired filter",
        "Select matching cues...", "Save synchronized SRT", "Analyze and synchronize",
    ]
    workflow = "\n".join("- " + translate(step, language) for step in steps)
    return (
        first + "\n- " + translate("Reference SRT (optional)", language) + "\n" + workflow
        + "\n\n" + second + "\n" + workflow
        + "\n\n" + translate("Example 3: Synchronize existing subtitles using the audio", language)
        + "\n" + "\n".join("- " + translate(step, language) for step in (
            "Sync to audio...", "Video / audio", "Inspect tracks", "Audio track",
            "Embedded subtitles", "External SRT", "Correct gradual drift / frame-rate mismatch",
            "Correct section-by-section timing shifts", "Save synchronized SRT",
            "Synchronize to audio", "Reference SRT (optional)",
        ))
        + "\n\n" + translate(
            "The synchronized output is automatically selected as the reference for the next synchronization.",
            language,
        )
        + " " + translate(
            "No transcription is performed; the existing subtitle text is preserved.",
            language,
        )
        + " " + translate(
            "Review the logged section boundaries and check the beginning, middle and end of the output in your player.",
            language,
        )
    )
